def polish(value):
 if isinstance(value,str):
  value=re.sub(r'[A-Za-z]{5,}',lambda m:SPACING.get(m.group(),m.group()),value)
  value=re.sub(r'([a-z]{3,})(?=[0-9])',r'\1 ',value)
  return value
 if isinstance(value,list):return [polish(x)for x in value]
 if isinstance(value,dict):return {k:(v if k in ['id','unit'] else polish(v))for k,v in value.items()}
